    @app.post("/api/options/save", dependencies=[Depends(admin)])
    async def options_save(request: Request, payload: dict = Body(...), me: Principal = Depends(current_user)):
        # the mail: not posted keeps the saved one; a password left empty too
        mail = payload.get("mail")
        if mail is None:
            current = settings.options
            payload = {**payload, "mail": {"host": current.smtp_host, "port": current.smtp_port,
                                           "security": current.smtp_security, "user": current.smtp_user,
                                           "password": current.smtp_password, "from": current.mail_from}}
        elif isinstance(mail, dict) and not mail.get("password"):
            payload = {**payload, "mail": {**mail, "password": settings.options.smtp_password}}
        if not isinstance(payload.get("monitor"), dict):
            payload = {**payload, "monitor": monitor_to_dict(settings.options)}
        else:
            # the webhooks' secrets are never in the page: kept
            payload = {**payload, "monitor": {**payload["monitor"],
                                              "webhooks": monitor_to_dict(settings.options).get("webhooks", {})}}
        if "audit" not in payload:
            # the access log's: not posted keeps the saved ones (a script of before)
            current = settings.options
            payload = {**payload, "audit": {"retention_days": current.audit_retention_days, "syslog": {
                "host": current.syslog_host, "port": current.syslog_port, "protocol": current.syslog_protocol,
                "ca_file": current.syslog_ca_file}}}
        current = settings.options
        portal = payload.get("portal")
        if not isinstance(portal, dict):
            # the name the customers read: not posted keeps the saved one
            portal = {"provider": current.provider_label}
        # the portal's address changes only when it is published (portal_publish):
        # its site is written with it
        payload = {**payload, "portal": {**portal, "address": current.portal_address,
                                         "staff": portal.get("staff", current.portal_staff),
                                         "second_factor": portal.get("second_factor", current.second_factor)}}
        if not isinstance(payload.get("brand"), dict):
            # the panel's name and colour (Whitelabel): not posted keeps the saved ones
            payload = {**payload, "brand": {"name": current.brand_name, "color": current.brand_color}}
        try:
            options = parse_options(payload)
        except ConfigError as exc:
            return refuse(str(exc))
        try:
            await asyncio.to_thread(save_options, settings.options_file, options)
        except OSError as exc:
            return refuse(f"Cannot write {settings.options_file}: {exc}", 500)
        settings.options = options
        apply_audit_options()
        audit_status_cache.clear()
        if options.second_factor != current.second_factor:
            access_log.record("second-factor", me.kind, me.name, request.client.host if request.client else "",
                              f"required for: {current.second_factor} -> {options.second_factor} (Options)")
        if (options.brand_name, options.brand_color) != (current.brand_name, current.brand_color):
            access_log.record("action", me.kind, me.name, request.client.host if request.client else "",
                              f"whitelabel: name {current.brand_name or brand.DEFAULT_NAME!r} -> "
                              f"{options.brand_name or brand.DEFAULT_NAME!r}, colour {current.brand_color or 'default'} -> "
                              f"{options.brand_color or 'default'} (Options)")
        return {"ok": True, "brand": brand.facts(options.brand_color)}

    @app.post("/api/options/brand/logo", dependencies=[Depends(admin)])
    async def brand_logo_save(request: Request, me: Principal = Depends(current_user)):
        """The panel's logo (Whitelabel): a PNG or an SVG as the request's body, at most brand.LOGO_MAX bytes."""
        if not machine_admin(me):
            raise HTTPException(status.HTTP_403_FORBIDDEN, "An admin of the machine is required")
        data = bytearray()
        async for chunk in request.stream():
            data += chunk
            if len(data) > brand.LOGO_MAX:
                return refuse(f"The logo is bigger than {brand.LOGO_MAX // 1024} kB")
        try:
            kind = await asyncio.to_thread(brand.save_logo, settings.options_file, bytes(data))
        except brand.BrandRefused as exc:
            return refuse(str(exc))
        except OSError as exc:
            return refuse(f"Cannot write the logo: {exc}", 500)
        access_log.record("action", me.kind, me.name, request.client.host if request.client else "",
                          f"whitelabel: logo set ({kind.upper()}, {len(data)} bytes) (Options)")
        return {"ok": True, "kind": kind, "url": f"{brand.LOGO_ROUTE}?v={brand.logo_version(settings.options_file)}"}

    @app.post("/api/options/brand/logo/delete", dependencies=[Depends(admin)])
    async def brand_logo_delete(request: Request, me: Principal = Depends(current_user)):
        """The panel's logo taken away: the OmniaSolutions «O» again."""
        if not machine_admin(me):
            raise HTTPException(status.HTTP_403_FORBIDDEN, "An admin of the machine is required")
        if await asyncio.to_thread(brand.remove_logo, settings.options_file):
            access_log.record("action", me.kind, me.name, request.client.host if request.client else "",
                              "whitelabel: logo taken away (Options)")
        return {"ok": True}

    # --- the webhooks of the notices: signed, told the jobs that fail (notify.py) ---

    def webhook_rows() -> list[dict]:
        """Each webhook of the machine's Monitoring and of the workspaces' notices,
        whether its body is signed and whether it is told the jobs that fail or warn."""
        keys, rows, seen = settings.options.webhook_keys, [], set()
        lists = [("", settings.options.monitor_notify)] + [(ws.label or ws.name, ws.notify)
                                                            for ws in sorted(settings.workspaces.values(), key=lambda w: w.name)]
        for where, urls in lists:
            for url in urls:
                if notify.is_email(url) or url in seen:
                    continue
                seen.add(url)
                parts = urlsplit(url)
                rows.append({"url": url, "where": where,
                             "shown": f"https://{parts.hostname}" + ("/…" if parts.path not in ("", "/") or parts.query else ""),
                             "signed": bool((keys.get(url) or {}).get("secret")), "jobs": bool((keys.get(url) or {}).get("jobs"))})
        return rows

    async def save_webhook(url: str, secret: str | None = None, jobs_: bool | None = None, unsign: bool = False):
        keys = {k: dict(v) for k, v in settings.options.webhook_keys.items()}
        entry = keys.get(url) or {"secret": "", "jobs": False}
        if secret is not None:
            entry["secret"] = secret
        if unsign:
            entry["secret"] = ""
        if jobs_ is not None:
            entry["jobs"] = jobs_
        if entry["secret"] or entry["jobs"]:
            keys[url] = entry
        else:
            keys.pop(url, None)
        options = dataclasses.replace(settings.options, webhook_keys=keys)
        await asyncio.to_thread(save_options, settings.options_file, options)
        settings.options = options

    def webhook_of(payload: dict) -> str:
        url = str(payload.get("url") or "")
        if url not in {r["url"] for r in webhook_rows()}:
            raise HTTPException(status.HTTP_404_NOT_FOUND, "Not a webhook of Monitoring or of a workspace's notices")
        return url

    @app.post("/api/options/webhooks/secret", dependencies=[Depends(admin)])
    async def webhook_secret(payload: dict = Body(...), me: Principal = Depends(current_user)):
        """A new secret the webhook's body is signed with (HMAC-SHA256): in the
        answer once, never shown again; the one of before stops signing."""
        if not machine_admin(me):
            raise HTTPException(status.HTTP_403_FORBIDDEN, "An admin of the machine is required")
        url = webhook_of(payload)
        secret = secrets.token_urlsafe(32)
        await save_webhook(url, secret=secret)
        return {"secret": secret, "webhooks": webhook_rows()}

    @app.post("/api/options/webhooks/save", dependencies=[Depends(admin)])
    async def webhook_save(payload: dict = Body(...), me: Principal = Depends(current_user)):
        """Whether the webhook is told the jobs that fail or warn; unsigned: its secret taken away."""
        if not machine_admin(me):
            raise HTTPException(status.HTTP_403_FORBIDDEN, "An admin of the machine is required")
        url = webhook_of(payload)
        await save_webhook(url, jobs_=bool(payload["jobs"]) if "jobs" in payload else None,
                           unsign=bool(payload.get("unsigned")))
        return {"webhooks": webhook_rows()}

    @app.post("/api/options/webhooks/test", dependencies=[Depends(admin)])
    async def webhook_test(request: Request, payload: dict = Body(...), me: Principal = Depends(current_user)):
        """A test notice to the webhook (event notice.test), signed when it has a secret."""
        if not machine_admin(me):
            raise HTTPException(status.HTTP_403_FORBIDDEN, "An admin of the machine is required")
        url = webhook_of(payload)
        problems = await notify.send(settings.options, [url], f"OmniaCLI {socket.gethostname()}: [info] a test notice",
                                     f"A test notice sent by {me} from Options › Monitoring.",
                                     event={"event": "notice.test", "level": "info"})
        lang = request_language(request)
        return {"ok": not problems, "problems": [i18n.tr(lang, p) for p in problems]}

    # --- the customers' portal: its address, published by the root helper ----

    def portal_refusal(me: Principal) -> str:
        """Why me may not publish the portal here, "" when it may: the admins of
        the machine only, where OmniaCLI keeps nginx (its workspaces)."""
        if not machine_admin(me):
            return "Only the administrators of the machine publish the customers' portal"
        if not settings.storage_roots:
            return workspacehelper.NOT_OUR_NGINX
        return ""

    def portal_name(value) -> str:
        """A host name for the portal, or ConfigError with why not: not one of
        the workspaces' names, nor under their domains."""
        name = address_name("address", value)
        taken = address_taken(name, settings.workspaces, "", "", "")
        if taken:
            raise ConfigError(f"address: {name} is taken: {taken}")
        return name

    def portal_certificate_said(host: str, error: str) -> str:
        """Why Let's Encrypt gave no certificate, in one sentence: certbot's
        own lines (its log, its forum) are in the job's log."""
        if any(mark in error.lower() for mark in ("challenges have failed", "failed to authenticate",
                                                   "connection refused", "timeout during connect")):
            return (f"Let's Encrypt did not reach {host} on port 80: its DNS record leads elsewhere, "
                    "or this machine is not reachable from the internet")
        lines = [line for line in error.splitlines()
                 if line.strip() and not line.startswith(("Saving debug log", "Ask for help"))]
        return "; ".join(lines)[:300]

    @app.get("/api/portal", dependencies=[Depends(admin)])
    async def portal_get(me: Principal = Depends(current_user)):
        """The portal's address and whether it may be published here."""
        return {"address": settings.options.portal_address, "url": portal_url(),
                "staff": settings.options.portal_staff, "refused": portal_refusal(me)}

    @app.post("/api/portal/check", dependencies=[Depends(admin)])
    async def portal_check(request: Request, payload: dict = Body(...), me: Principal = Depends(current_user)):
        """The address as the Options page shows it before Publish: a host
        name, free (the workspaces, the other sites of nginx), and where its
        DNS points: here, elsewhere (with this machine's address), none."""
        lang = request_language(request)
        refused = portal_refusal(me)
        if refused:
            return refuse(refused)
        row = {"name": str(payload.get("host") or "").strip().lower().rstrip("."), "error": "", "taken": "",
               "dns": "", "addresses": []}
        try:
            row["name"] = portal_name(payload.get("host"))
        except ConfigError as exc:
            row["error"] = i18n.tr(lang, str(exc).removeprefix("address: "))
            return row
        try:
            found = await workspaceops.ask("portal-names")
            hit = workspaceweb.takers(row["name"], {str(k): str(v) for k, v in (found.get("elsewhere") or {}).items()})
            if hit:
                row["taken"] = i18n.tr(lang, f"used by {hit[0][1]}")
        except JobFailed as exc:
            row["nginx_error"] = i18n.tr(lang, str(exc).removeprefix("workspace-helper: "))
        here = await asyncio.to_thread(workspaceweb.machine_addresses, shutil.which("ip"))
        row["addresses"] = await asyncio.to_thread(workspaceweb.addresses_of, row["name"])
        row["dns"], row["here"] = workspaceweb.dns_state(row["addresses"], here), sorted(here)
        return row

    @app.post("/api/portal/publish", dependencies=[Depends(admin)])
    async def portal_publish(payload: dict = Body(...), me: Principal = Depends(current_user)):
        """The portal published on host (empty: taken away), as a job: the
        site, the certificate, then the address saved in the options."""
        refused = portal_refusal(me)
        if refused:
            return refuse(refused)
        given = str(payload.get("host") or "").strip()
        try:
            host = portal_name(given) if given else ""
        except ConfigError as exc:
            return refuse(str(exc).removeprefix("address: "))

        async def action(job):
            if host:
                job.log(f"--- the customers' portal at {host}")
            else:
                job.log("--- the customers' portal taken away" + (f" from {settings.options.portal_address}"
                                                                 if settings.options.portal_address else ""))
            made = await workspaceops._helper(job, "portal", host or "-")
            job.log(f"nginx: {made.get('nginx')}")
            options = dataclasses.replace(settings.options, portal_address=host)
            try:
                await asyncio.to_thread(save_options, settings.options_file, options)
            except OSError as exc:
                raise JobFailed(f"the site is written, but {settings.options_file} is not: {exc}") from exc
            settings.options = options
            job.result.update(made)
            if not host:
                return
            job.log(f"https://{host}")
            why = portal_certificate_said(host, str(made.get("certificate_error") or ""))
            if made.get("certificate_error"):
                job.log(f"Let's Encrypt: {made['certificate_error']}")
            if made.get("certificate") == "self-signed":
                job.warn(f"{host} has a certificate of this machine's own for now, which the browsers warn about: "
                         f"Let's Encrypt's comes once {host} points here and the portal is published again"
                         + (f" ({why})" if why else ""))
            elif not made.get("https"):
                job.warn(f"{host} has no certificate yet: {why or 'openssl did not make one'}")
        title = f"Customers' portal at {host}" if host else "Customers' portal taken away"
        return {"ok": True, "job": jobs.submit(title, [], f"manual: {me}", action).id}

    # --- scheduled actions ----------------------------------------------

    schedules_lock = asyncio.Lock()

    def schedule_view(sch: schedules.Schedule) -> dict:
        try:
            upcoming = [t.isoformat(sep=" ", timespec="minutes") for t in schedules.next_runs(sch.cron)]
        except (ValueError, KeyError):
            upcoming = []
        return {"name": sch.name, "data": schedules.schedule_to_dict(sch), "steps": sch.steps,
                "user": sch.acting_user, "next": upcoming if sch.enabled else [],
                "live": scheduler.instance_of(sch) is not None,
                "runs": scheduler.history.runs(sch.name, jobs)}

    @app.get("/schedules", dependencies=[Depends(admin)])
    async def schedules_page(request: Request):
        targets = {}
        for srv in settings.servers.values():
            plugin = plugins.registry().get(srv.type)
            for inst in srv.instances.values():
                src = inst.from_link
                targets[inst.key] = {
                    "live": srv.active,
                    "type": srv.type,
                    "has_restore": bool(plugin and plugin.has_restore),
                    "has_backup": bool(plugin and plugin.has_backup),
                    "backup_fields": [_field_dict(f) for f in plugin.backup_fields()] if plugin else [],
                    "restore_fields": [_field_dict(f) for f in plugin.restore_fields()] if plugin else [],
                    "from_link": src.to_dict() if src else None,
                }
        return _TEMPLATES.TemplateResponse(
            request, "schedules.html",
            {"schedules": [schedule_view(s) for s in scheduler.schedules.values()], "targets": targets,
             "links": list(settings.link_targets), "connections": list(settings.connections),
             "scripts": schedules.list_scripts(settings.scripts_dir),
             "scripts_dir": settings.scripts_dir, "schedules_file": settings.schedules_file,
             "load_error": schedules_error, "default_user": schedules.DEFAULT_USER},
        )

    @app.get("/api/schedules/next", dependencies=[Depends(admin)])
    async def schedules_next(cron: str = ""):
        """The next runs of a crontab expression, for the form."""
        try:
            expr = schedules.check_cron(cron, "cron")
        except ConfigError as exc:
            return refuse(str(exc).removeprefix("cron: "))
        return {"cron": expr, "next": [t.isoformat(sep=" ", timespec="minutes")
                                       for t in schedules.next_runs(expr, 5)]}

    @app.post("/api/schedules/save", dependencies=[Depends(admin)])
    async def schedules_save(payload: dict = Body(...)):
        nonlocal schedules_error
        original = payload.get("original") or None
        name = str(payload.get("name") or "").strip()
        data = dict(payload.get("schedule") or {})
        async with schedules_lock:
            current = scheduler.schedules
            if original is not None and original not in current:
                return refuse(f"Schedule {original} no longer exists", status.HTTP_404_NOT_FOUND)
            if name != original and name in current:
                return refuse(f"A schedule named {name} already exists")
            server, _, role = str(data.get("instance") or "").partition("/")
            srv = settings.servers.get(server)
            if srv is None or role not in srv.instances:
                return refuse(f"No instance {data.get('instance')}")
            instance = srv.instances[role]
            # what this form does not show stays as it was: the destination of
            # the backup and whom to tell (the instance's Backups tab sets them)
            before = current.get(original) if original is not None else None
            if before is not None and "notify" not in data:
                data["notify"] = list(before.notify)
            backup = data.get("backup")
            if backup and before is not None and before.backup and "destination" not in backup:
                backup["destination"] = before.backup.destination
            if backup:
                if not instance.plugin.has_backup:
                    return refuse(f"{instance.plugin.label} has no backup")
                try:
                    backup["options"] = {f.key: _field_value(f, (backup.get("options") or {}).get(f.key))
                                         for f in instance.plugin.backup_fields() if f.kind == "checkbox"}
                except ActionRefused as exc:
                    return refuse(str(exc))
            copy = data.get("copy")
            if copy:
                if not instance.plugin.has_restore:
                    return refuse(f"{instance.plugin.label} cannot restore a database: no copy from link")
                # the choices as the instance's plugin asks them
                try:
                    # the checkboxes: the other fields come from the last
                    # backup dialog of the instance there
                    copy["backup_options"] = {f.key: _field_value(f, (copy.get("backup_options") or {}).get(f.key))
                                              for f in instance.plugin.backup_fields() if f.kind == "checkbox"}
                    copy["restore_options"] = {
                        f.key: _field_value(f, (copy.get("restore_options") or {}).get(f.key))
                        for f in instance.plugin.restore_fields()}
                except ActionRefused as exc:
                    return refuse(str(exc))
            try:
                parsed = schedules.parse_schedule(name, data)
            except (ConfigError, TypeError, ValueError, AttributeError) as exc:
                return refuse(str(exc))
            updated = {}
            for key, sch in current.items():
                # an edited schedule keeps its place in the list
                updated[name if key == original else key] = parsed if key == original else sch
            updated.setdefault(name, parsed)
            try:
                await asyncio.to_thread(schedules.save_schedules, settings.schedules_file, updated)
            except OSError as exc:
                return refuse(f"Cannot write {settings.schedules_file}: {exc}", 500)
            if original and original != name:
                scheduler.history.rename(original, name)
            scheduler.schedules = updated
            schedules_error = ""
        return {"ok": True}

    @app.post("/api/schedules/delete", dependencies=[Depends(admin)])
    async def schedules_delete(payload: dict = Body(...)):
        name = str(payload.get("name") or "")
        async with schedules_lock:
            if name not in scheduler.schedules:
                return refuse(f"No schedule {name}", status.HTTP_404_NOT_FOUND)
            updated = {k: v for k, v in scheduler.schedules.items() if k != name}
            try:
                await asyncio.to_thread(schedules.save_schedules, settings.schedules_file, updated)
            except OSError as exc:
                return refuse(f"Cannot write {settings.schedules_file}: {exc}", 500)
            scheduler.schedules = updated
            scheduler.history.keep_only(updated)
        return {"ok": True}

    @app.post("/api/schedules/{name}/run")
    async def schedules_run(name: str, user: Principal = Depends(admin)):
        """Run the schedule now, enabled or not."""
        sch = scheduler.schedules.get(name)
        if sch is None:
            return refuse(f"No schedule {name}", status.HTTP_404_NOT_FOUND)
        job = scheduler.fire(sch, f"manual: {user}")
        if job is None:
            return refuse(scheduler.history.data[name][0]["message"])
        return {"job": job.id}

    # --- the automatic backups of an instance (its Backups tab) ---------

    def backup_schedule_name(instance: Instance) -> str:
        """The schedule of an instance's automatic backups: one per instance,
        a schedule as the others (the Schedules page shows it too)."""
        return f"backup.{instance.server}.{instance.role}"

    def backup_schedule_view(instance: Instance, me: Principal) -> dict:
        sch = scheduler.schedules.get(backup_schedule_name(instance))
        backup = sch.backup if sch is not None else None
        rotation = ({k: getattr(backup, k) for k in schedules.DEFAULT_ROTATION} if backup is not None
                    else dict(schedules.DEFAULT_ROTATION))
        time = "03:00"
        if sch is not None:
            minute, hour, *rest = sch.cron.split(" ")
            if minute.isdigit() and hour.isdigit() and rest == ["*", "*", "*"]:
                time = f"{int(hour):02d}:{int(minute):02d}"
        runs = scheduler.history.runs(sch.name, jobs) if sch is not None else []
        try:
            upcoming = schedules.next_runs(sch.cron, 1)[0].isoformat(sep=" ", timespec="minutes") \
                if sch is not None and sch.enabled else None
        except (ValueError, KeyError):
            upcoming = None
        return {"exists": sch is not None, "enabled": bool(sch and sch.enabled and backup), "time": time,
                "cron": sch.cron if sch is not None else "", **rotation,
                "options": dict(backup.options) if backup is not None else {},
                "next": upcoming, "last": runs[0] if runs else None,
                # the schedule runs at this machine's time
                "zone": datetime.datetime.now().astimezone().tzname() or "",
                "fields": [_field_dict(f) for f in instance.plugin.backup_fields() if f.kind == "checkbox"],
                "destination": backup.destination if backup is not None else "",
                "verify": backup is not None and backup.verify_weekday is not None,
                "archive": bool(backup and backup.archive),
                "has_verify": instance.plugin.has_verify,
                "verified": last_verified(instance),
                "destinations": [{"name": d.name, "label": d.label, "path": d.path, "workspace": d.workspace}
                                 for d in destination_choices(instance, me, backup.destination if backup else "")],
                "notify": list(sch.notify) if sch is not None else [],
                "can_edit": me.can(backup_role(instance))}

    def last_verified(instance: Instance) -> dict | None:
        """The newest restore tried of the instance's backups: {file, time, ok, ...}."""
        found = [{"file": name, **entry["verified"]} for name, entry in
                 backupcheck.load(backup_folder(instance)).items() if (entry or {}).get("verified")]
        return max(found, key=lambda v: v.get("time") or "") if found else None

    def load_destinations() -> dict:
        try:
            return destinations.load_destinations(settings.destinations_file)
        except ConfigError as exc:
            _logger.warning("%s", exc)
            return {}

    def machine_admin(me: Principal) -> bool:
        """An admin of the machine (a user, a token, a link acting as one), not
        of a workspace only."""
        return not me.workspaces and me.can("admin")

    def destination_choices(instance: Instance, me: Principal, current: str = "") -> list:
        """The destinations the instance's backups may go to, for me: the
        workspaces' it is in, the machine's for the machine's admins; and the
        one chosen now, whoever chose it."""
        found = load_destinations()
        here = {ws.name for ws in settings.workspaces.values() if instance.server in ws.servers}
        return [d for d in found.values()
                if (d.workspace in here) or (not d.workspace and machine_admin(me)) or d.name == current]

    def backup_role(instance: Instance) -> str:
        """Who may delete an instance's backups and set its automatic ones:
        a production's are an admin's."""
        return "admin" if instance.role == "production" else "developer"

    @app.get("/api/servers/{server}/{role}/backup-schedule", dependencies=[Depends(developer)])
    async def backup_schedule_get(server: str, role: str, me: Principal = Depends(current_user)):
        """The automatic backups of the instance: when, the rotation, the
        choices, the last run."""
        return backup_schedule_view(get_instance(server, role), me)

    @app.post("/api/servers/{server}/{role}/backup-schedule")
    async def backup_schedule_save(server: str, role: str, payload: dict = Body(...),
                                   me: Principal = Depends(current_user)):
        """The automatic backups of the instance saved: every day at a time,
        kept by a rotation (days, weeks, months); off keeps the schedule's
        other steps, or removes it when it has none."""
        instance = get_instance(server, role)
        if not me.can(backup_role(instance)):
            raise HTTPException(status.HTTP_403_FORBIDDEN, f"The {backup_role(instance)} role is required")
        if not instance.plugin.has_backup:
            return refuse(f"{instance.plugin.label} has no backup")
        name = backup_schedule_name(instance)
        if not schedules.SCHEDULE_NAME.fullmatch(name):
            return refuse(f"The server's name is too long for a schedule ({name})")
        time = str(payload.get("time") or "").strip()
        found = re.fullmatch(r"([01]?\d|2[0-3]):([0-5]\d)", time)
        if found is None:
            return refuse(f"{time!r} is not a time HH:MM")
        enabled = bool(payload.get("enabled"))
        try:
            options = {f.key: _field_value(f, (payload.get("options") or {}).get(f.key))
                       for f in instance.plugin.backup_fields() if f.kind == "checkbox"}
        except ActionRefused as exc:
            return refuse(str(exc))
        async with schedules_lock:
            current = scheduler.schedules.get(name)
            data = schedules.schedule_to_dict(current) if current is not None else {
                "instance": instance.key, "user": me.name if me.kind == "user" else ""}
            destination = str(payload.get("destination") or "")
            was = current.backup.destination if current is not None and current.backup else ""
            if destination and destination != was and destination not in [
                    d.name for d in destination_choices(instance, me)]:
                return refuse(f"No destination {destination} for {instance.key}")
            # a restore tried every Sunday: on, or as it was
            weekday = (current.backup.verify_weekday if current is not None and current.backup else None)
            if "verify" in payload:
                weekday = VERIFY_WEEKDAY if payload.get("verify") and instance.plugin.has_verify else None
            data.update({"cron": f"{int(found[2])} {int(found[1])} * * *", "enabled": True,
                         "backup": {"options": options, "destination": destination, "verify_weekday": weekday,
                                    "archive": bool(payload.get("archive", current.backup.archive
                                                                if current is not None and current.backup else False)),
                                    **{k: payload.get(k) for k in schedules.DEFAULT_ROTATION}}})
            if "notify" in payload:
                data["notify"] = payload.get("notify") or []
            if not enabled:
                data.pop("backup")
            updated = dict(scheduler.schedules)
            if not enabled and not (data.get("pull") or data.get("copy") or data.get("script")):
                updated.pop(name, None)
            else:
                try:
                    updated[name] = schedules.parse_schedule(name, data)
                except ConfigError as exc:
                    return refuse(str(exc).removeprefix(f"schedules.{name}."))
            try:
                await asyncio.to_thread(schedules.save_schedules, settings.schedules_file, updated)
            except OSError as exc:
                return refuse(f"Cannot write {settings.schedules_file}: {exc}", 500)
            scheduler.schedules = updated
            scheduler.history.keep_only(updated)
        return {"ok": True, **backup_schedule_view(instance, me)}

    # --- deploy on push (deployhooks.py) -------------------------------------
    # A production is updated by hand only (Carlo, 22/11/2026: «the CI runs on the stagings, a production is
    # rebuilt by hand only»): deploy on push and the auto update are for a test and a staging. A push of a
    # branch a production follows is listed on it as a new commit available, not deployed, and deploys its
    # stagings of this machine that follow that branch.

    deploy_hooks_file = settings.servers_file.parent / deployhooks.FILE
    BY_HAND = ("A production is updated by hand only: deploy on push and the auto update are for its test "
               "and its stagings")

    def manual_only(instance) -> bool:
        """A production (not a staging, whose instance is a production too): updated by hand only."""
        return instance.role == "production" and instance.server not in stagings.load(stagings_file)

    def ci_on(instance: Instance) -> bool:
        """The CI of the instance (its switch «CI: update at every push», one per
        instance): a test or a staging with its webhook's secret, not switched
        off. Off, nothing moves its code by itself: no push, no auto update, no
        scheduled pull (deploys.paused holds who switched it off, and when)."""
        hook = deployhooks.load(deploy_hooks_file).get(instance.key) or {}
        return bool(hook.get("secret")) and not manual_only(instance) \
            and not deploys.paused(deploys_folder, instance.key)

    def deploy_hook_view(request: Request, instance: Instance, me: Principal) -> dict:
        hook = deployhooks.load(deploy_hooks_file).get(instance.key) or {}
        # on the instance's own name when it has one (its nginx passes it here):
        # OmniaCLI itself may answer on 127.0.0.1 only
        # read through a link, this request's address is the tunnel's of the panel that asks (127.0.0.1:<port>),
        # which no repository reaches: without a name or a portal address, the place of the address is said
        base = public_base(request) if portal_url() or not prefix_of(request) else "https://<address of this OmniaCLI>"
        url = (f"{instance.site}{workspaceweb.HOOKS_PATH}deploy/{instance.server}/{instance.role}" if instance.site
               else base + f"/hooks/deploy/{instance.server}/{instance.role}")
        lang, view = request_language(request), customer_view(request)
        off = deploys.paused(deploys_folder, instance.key) if hook.get("secret") else None
        last = dict(hook["last"]) if isinstance(hook.get("last"), dict) else None
        if last:
            last["result"] = i18n.tr(lang, view.text(last.get("result") or "") if view else last.get("result") or "")
        return {"enabled": ci_on(instance), "webhook": bool(hook.get("secret")), "url": url, "last": last,
                "off": {**off, "by": view.who(str(off.get("by") or "")) if view else off.get("by")} if off else None,
                "can_edit": me.can(backup_role(instance)), "role": backup_role(instance),
                "manual": manual_only(instance), "manual_reason": i18n.tr(lang, BY_HAND),
                "auto_update": instance.auto_update.enabled,
                "follows": [{"name": r.name, "branch": r.branch} for r in instance.repositories],
                "repositories": [r.name for r in instance.repositories]}

    # --- the update without stopping (zerodowntime.py) ------------------------
    # Per instance, off by default, kept in its file of deploys: an instance of a workspace (a compose project
    # made from a template, whose nginx OmniaCLI writes), served by its name with https. It changes how an update
    # runs, never when: a production still moves by hand only.

    def zero_downtime_problem(instance: Instance) -> str | None:
        """Why the instance cannot be updated without stopping, None when it can."""
        found = workspace_of(instance.server)
        if instance.restart.type != "compose" or instance.type != "docker" or found is None:
            return "only an instance of a workspace, whose nginx OmniaCLI writes, is updated without stopping"
        ws, _ = found
        if not ws.storage:
            return f"workspace {ws.name} has no storage: its instances have no site"
        if not ws.domain or not (instance.site or "").startswith("https://"):
            return "it has no name served with https yet (the names of its workspace, published)"
        if not instance.repositories:
            return "it has no repository: its code is the image's, with nothing to copy"
        return None

    def zero_downtime_of(instance) -> "zerodowntime.Target | str | None":
        """How an update of the instance runs (zerodowntime.choice): None off."""
        if not isinstance(instance, Instance) or not deploys.zero_downtime(deploys_folder, instance.key):
            return None
        problem = zero_downtime_problem(instance)
        if problem:
            return problem
        ws, name = workspace_of(instance.server)
        return zerodowntime.Target(workspace=ws.name, storage=ws.storage, instance=name, role=instance.role,
                                   url=instance.site.rstrip("/"), project=Path(instance.restart.service))

    def site_of(instance) -> "zerodowntime.Target | None":
        """The instance's site when its workspace's nginx serves it with https (the maintenance page of a normal
        update, zerodowntime.site), switched to the update without stopping or not."""
        if not isinstance(instance, Instance) or instance.restart.type != "compose" or instance.type != "docker":
            return None
        found = workspace_of(instance.server)
        if found is None or not found[0].storage or not found[0].domain \
                or not (instance.site or "").startswith("https://"):
            return None
        ws, name = found
        return zerodowntime.Target(workspace=ws.name, storage=ws.storage, instance=name, role=instance.role,
                                   url=instance.site.rstrip("/"), project=Path(instance.restart.service))

    zerodowntime.configure(zero_downtime_of, site_of)

    def zero_downtime_view(request: Request, instance: Instance, me: Principal) -> dict:
        lang, view = request_language(request), customer_view(request)
        on = deploys.zero_downtime(deploys_folder, instance.key)
        problem = zero_downtime_problem(instance)
        return {"enabled": bool(on), "can_edit": me.can(backup_role(instance)), "role": backup_role(instance),
                "available": problem is None, "reason": i18n.tr(lang, problem) if problem else None,
                "on": {**on, "by": view.who(str(on.get("by") or "")) if view else on.get("by")} if on else None}

    @app.get("/api/servers/{server}/{role}/zero-downtime", dependencies=[Depends(developer)])
    async def zero_downtime_get(request: Request, server: str, role: str, me: Principal = Depends(current_user)):
        return zero_downtime_view(request, get_instance(server, role), me)

    @app.post("/api/servers/{server}/{role}/zero-downtime")
    async def zero_downtime_save(request: Request, server: str, role: str, payload: dict = Body(...),
                                 me: Principal = Depends(current_user)):
        """{"enabled": true|false}: the updates of the instance without
        stopping, or the normal ones. Its role is the backup role, as the CI's."""
        instance = get_instance(server, role)
        if not me.can(backup_role(instance)):
            raise HTTPException(status.HTTP_403_FORBIDDEN, f"The {backup_role(instance)} role is required")
        enabled = bool(payload.get("enabled"))
        if enabled and zero_downtime_problem(instance):
            return refuse(zero_downtime_problem(instance))
        await asyncio.to_thread(deploys.set_zero_downtime, deploys_folder, instance.key, str(me) if enabled else None)
        access_log.record("action", me.kind, me.name, request.client.host if request.client else "",
                          f"Update without stopping of {instance.key}: {'on' if enabled else 'off'}")
        return zero_downtime_view(request, instance, me)

    @app.get("/api/servers/{server}/{role}/deploy-hook", dependencies=[Depends(developer)])
    async def deploy_hook_get(request: Request, server: str, role: str, me: Principal = Depends(current_user)):
        instance = get_instance(server, role)
        return {**deploy_hook_view(request, instance, me), "github": await github_view(request, instance)}

    @app.post("/api/servers/{server}/{role}/deploy-hook")
    async def deploy_hook_save(request: Request, server: str, role: str, payload: dict = Body(...),
                               me: Principal = Depends(current_user)):
        """The CI of the instance: {"enabled": true} on (its webhook's secret
        made the first time, in the answer once), {"enabled": false} off (the
        secret kept: on again, the webhook works as it was), {"new_secret":
        true} a new one, {"forget": true} the webhook taken away. Its role is
        the backup role (a production's or a staging's: an admin, of the
        machine or of its workspace; a test's: a developer). Not on a
        production, updated by hand only: there only forget."""
        instance = get_instance(server, role)
        if not me.can(backup_role(instance)):
            raise HTTPException(status.HTTP_403_FORBIDDEN, f"The {backup_role(instance)} role is required")
        data = deployhooks.load(deploy_hooks_file)
        secret, said = None, ""
        if payload.get("forget"):
            data.pop(instance.key, None)
            await asyncio.to_thread(deploys.set_paused, deploys_folder, instance.key, None)
            said = "webhook taken away"
        elif manual_only(instance):
            return refuse(BY_HAND)
        elif payload.get("new_secret") or (payload.get("enabled") and not (data.get(instance.key) or {}).get("secret")):
            secret = deployhooks.new_secret()
            data[instance.key] = {**(data.get(instance.key) or {}), "secret": secret, "by": me.name}
            said = "new secret" if payload.get("new_secret") else "on"
        if not payload.get("forget") and "enabled" in payload:
            await asyncio.to_thread(deploys.set_paused, deploys_folder, instance.key,
                                    None if payload.get("enabled") else str(me))
            said = said or ("on" if payload.get("enabled") else "off")
        await asyncio.to_thread(deployhooks.save, deploy_hooks_file, data)
        access_log.record("action", me.kind, me.name, request.client.host if request.client else "",
                          f"CI of {instance.key}: {said or 'unchanged'}")
        # the webhooks on GitHub of its repositories follow the switch (made, or taken away when no instance here
        # with the CI on follows them any more): a job, which says what it did
        sync = None
        if payload.get("forget") or "enabled" in payload:
            urls = {await remote_url(r) for r in instance.repositories} - {""}
            if await github_touches(instance, urls):
                ws = workspace_of(instance.server)
                sync = jobs.submit(f"GitHub webhooks of {instance.key}", [instance.key], f"manual: {me}",
                                   lambda job: github_sync(job, urls), workspace=ws[0].name if ws else "")
        return {**deploy_hook_view(request, instance, me), "secret": secret,
                "github": await github_view(request, instance), "github_job": sync.id if sync else None}

    async def followed_by(instance: Instance, urls: set, branch: str | None) -> list[str]:
        """The repositories of instance at one of urls (host/path) on branch."""
        found = []
        for repo in instance.repositories:
            code, out = await ops.capture(repo.git("remote", "get-url", repo.remote), cwd=repo.path)
            if code == 0 and deployhooks.host_path(out.strip()) in urls and repo.branch == branch:
                found.append(repo.name)
        return found

    # (instance, commit) of the pushes deployed in the last PUSH_TWICE seconds, with their job: the same push told
    # twice (its webhook pasted by hand and the one OmniaCLI made on GitHub) deploys once
    pushes_seen: dict[tuple[str, str], tuple[float, str]] = {}
    PUSH_TWICE = 600

    def push_deploy(instance: Instance, followed: list[str], branch: str | None, sha: str = ""):
        """The job of a push on a test or a staging; None when its automatic
        deploys are paused; the job of before when the same commit was just
        deployed by another webhook. Its state is written on the commit on
        GitHub when a GitHub token of the instance may (github_status)."""
        if deploys.paused(deploys_folder, instance.key):
            return None
        now = time.monotonic()
        for seen, (when, _) in list(pushes_seen.items()):
            if now - when > PUSH_TWICE:
                pushes_seen.pop(seen, None)
        if sha and (instance.key, sha) in pushes_seen:
            before = jobs.get(pushes_seen[(instance.key, sha)][1])
            if before is not None:
                return before
        ws = workspace_of(instance.server)

        async def action(job):
            targets = await github_targets(instance, followed)
            await github_status(job, instance, targets, "pending", sha)
            try:
                await ops.pull_restart(job, instance, only_if_changed=True, only=set(followed),
                                       backup_folder=backup_folder(instance))
            except asyncio.CancelledError:
                await github_status(job, instance, targets, "error", sha)
                raise
            except Exception:
                await github_status(job, instance, targets, "failure", sha)
                raise
            await github_status(job, instance, targets, "success", "")

        job = jobs.submit(f"Deploy on push {', '.join(followed)} to {instance.key}", [instance.key],
                          f"push ({branch})", action, workspace=ws[0].name if ws else "")
        if sha:
            pushes_seen[(instance.key, sha)] = (now, job.id)
        return job

    async def note_available(instance: Instance, followed: list[str], branch: str | None, sha: str,
                             message: str, author: str = "") -> bool:
        """The commit a push brought, listed in the deploys of a production as
        available, not deployed (its page says so until it is pulled by hand)."""
        rows = []
        # the same push told by two webhooks (one pasted by hand, the one made on GitHub) is listed once
        listed = {(r.get("name"), r.get("after")) for e in deploys.load(deploys_folder, instance.key)["deploys"][-20:]
                  if e.get("kind") == "available" for r in e.get("repositories") or [] if isinstance(r, dict)}
        for repo in instance.repositories:
            if repo.name not in followed:
                continue
            now = await deploys.head(repo)
            if sha and now and now.startswith(sha):
                continue
            if sha and (repo.name, sha) in listed:
                continue
            rows.append({"name": repo.name, "branch": repo.branch, "before": now, "after": sha or None,
                         "subject": message, "author": author, "before_subject": "", "brought": None, "taken": None,
                         "commits": []})
        if not rows:
            return False
        stamp = datetime.datetime.now().isoformat(timespec="seconds")
        await asyncio.to_thread(deploys.record, deploys_folder, instance.key, {
            "id": "available-" + datetime.datetime.now().strftime("%Y%m%d-%H%M%S-") + secrets.token_hex(3),
            "kind": "available", "started": stamp, "finished": stamp, "outcome": "available",
            "title": f"New commit available on {', '.join(r['name'] for r in rows)} of {instance.key}",
            "by": f"push ({branch})", "error": None, "repositories": rows, "state": None, "backup": None,
            "back_to": None})
        return True

    def local_stagings(server: str) -> list[Instance]:
        """The stagings of this machine made from the production of server."""
        return [settings.servers[name].production for name, row in stagings.load(stagings_file).items()
                if row.get("parent") == server and not row.get("machine") and name in settings.servers
                and settings.servers[name].production is not None]

    def production_of(instance: Instance) -> Instance | None:
        """The production a test or a staging of this machine is made from (for a new commit available)."""
        if instance.role == "test":
            return settings.servers[instance.server].production
        row = stagings.load(stagings_file).get(instance.server) or {}
        parent = settings.servers.get(row.get("parent") or "") if not row.get("machine") else None
        return parent.production if parent is not None else None

    async def deploy_hook_call(request: Request):
        """A push told by GitHub, GitLab, Bitbucket or a CI: with the
        instance's secret, the repository pushed pulled if the instance (a
        test, a staging) follows that branch, then the changed modules and a
        restart; on a production, the new commit listed (it is updated by
        hand) and its stagings on that branch deployed. A Starlette route:
        no login, the secret is its check."""
        server, role = request.path_params["server"], request.path_params["role"]
        instance = settings.instance(server, role) if role in ROLES else None
        hook = deployhooks.load(deploy_hooks_file).get(f"{server}/{role}") or {}
        body = await request.body()
        headers = {k.lower(): v for k, v in request.headers.items()}
        ip = request.client.host if request.client else ""
        if instance is None or not deployhooks.verified(headers, body[:deployhooks.MAX_BODY], hook.get("secret", "")):
            access_log.record("failed", "hook", "", ip, f"deploy {server}/{role}")
            return JSONResponse({"error": "Unknown instance or wrong secret"}, status_code=403)
        if headers.get("x-github-event") == "ping" or headers.get("x-gitlab-event") == "System Hook":
            return JSONResponse({"ok": True, "pong": True})
        branch, urls = deployhooks.pushed(body)
        sha, message = deployhooks.head_commit(body)
        author = deployhooks.head_author(body)
        record = {"time": datetime.datetime.now().isoformat(timespec="seconds"), "branch": branch}
        started = []
        if manual_only(instance):
            followed = await followed_by(instance, urls, branch)
            if followed:
                await note_available(instance, followed, branch, sha, message, author)
                record["result"] = (f"not deployed: {instance.key} is a production, updated by hand only; "
                                    f"the new commit of {', '.join(followed)} is listed on its page")
            else:
                record["result"] = f"nothing to do: {instance.key} follows no pushed branch {branch or '?'} of that repository"
            # its stagings here on that branch whose CI is on: that is the CI
            for staging in local_stagings(server):
                theirs = await followed_by(staging, urls, branch)
                job = push_deploy(staging, theirs, branch, sha) if theirs and ci_on(staging) else None
                if theirs:
                    started.append({"instance": staging.key, "job": job.id if job else None,
                                    "note": None if job else "CI off"})
            if started:
                record["stagings"] = started
        else:
            stopped = deploys.paused(deploys_folder, instance.key)
            followed = await followed_by(instance, urls, branch)
            if stopped:
                record["result"] = (f"not deployed: the CI of {instance.key} is off "
                                    f"(by {stopped.get('by') or '?'} since {stopped.get('at') or '?'})")
            elif not followed:
                record["result"] = f"nothing to do: {instance.key} follows no pushed branch {branch or '?'} of that repository"
            else:
                job = push_deploy(instance, followed, branch, sha)
                started.append({"instance": instance.key, "job": job.id, "note": None})
                record.update(result="deploy", job=job.id, repositories=followed)
            # its production on the same branch: told of the commit, not deployed
            prod = production_of(instance)
            if prod is not None and prod.key != instance.key and manual_only(prod):
                theirs = await followed_by(prod, urls, branch)
                if theirs:
                    await note_available(prod, theirs, branch, sha, message, author)
        access_log.record("action", "hook", "push", ip, f"deploy {instance.key}: {record['result']}")
        data = deployhooks.load(deploy_hooks_file)
        if instance.key in data:
            data[instance.key]["last"] = record
            await asyncio.to_thread(deployhooks.save, deploy_hooks_file, data)
        jobs_started = [s["job"] for s in started if s["job"]]
        answer = {"ok": True, "note": record["result"]}
        if jobs_started:
            answer["job"] = jobs_started[0]
            answer["jobs"] = jobs_started
        if record["result"].startswith("not deployed: the CI"):
            answer["paused"] = True
        return JSONResponse(answer, status_code=202 if jobs_started else 200)

    # --- GitHub (github.py): the webhook of a repository made by itself, the state of a deploy on its commit ---
    # One webhook per repository and machine, made when an instance here that follows the repository has its CI
    # switched on (or the repository is added to one that has it on), with the GitHub token of that instance's
    # credentials, on an address GitHub reaches (the portal's, else an instance's own name); taken away when no
    # instance here with the CI on follows it. Its address is /hooks/github/<id> (its mark: only those are
    # changed or taken away) and its secret is its own (github-hooks.json, 600). A push it tells is fanned out to
    # every instance here that follows that repository and branch, as the per-instance webhook does: a test or a
    # staging with the CI on deploys, a production is told of the new commit and does not move.

    github_hooks_file = settings.servers_file.parent / "github-hooks.json"
    github_lock = asyncio.Lock()

    async def remote_url(repo) -> str:
        if not repo.path.is_dir():
            return ""
        code, out = await ops.capture(repo.git("remote", "get-url", repo.remote), cwd=repo.path)
        return out.strip() if code == 0 else ""

    def github_key(url: str) -> str | None:
        found = github.repository_of(url)
        return github.key_of(*found) if found else None

    async def github_followers(key: str) -> list[Instance]:
        """Every instance of this machine with a repository at key."""
        found = []
        for inst in settings.all_instances():
            for repo in inst.repositories:
                if github_key(await remote_url(repo)) == key:
                    found.append(inst)
                    break
        return found

    def github_token_of(host: str, servers) -> tuple[str, gitcredentials.Credential] | None:
        """(server, its GitHub token for host) of the first of servers that has one."""
        for server in servers:
            cred = gitcredentials.github_tokens(settings, server).get(host)
            if cred is not None:
                return server, cred
        return None

    async def github_touches(instance: Instance, urls: set) -> bool:
        """Whether one of urls is a repository a GitHub token of the instance reaches, or one whose webhook
        OmniaCLI made (a sync has something to do)."""
        made = await asyncio.to_thread(deployhooks.load, github_hooks_file)
        tokens = gitcredentials.github_tokens(settings, instance.server)
        for url in urls:
            found = github.repository_of(url)
            if found and (found[0] in tokens or github.key_of(*found) in made):
                return True
        return False

    def github_hook_base(wanting: list[Instance]) -> tuple[str | None, str]:
        """The address GitHub calls (…/hooks/github/, the id after it): the
        portal's, else the own name of one of the instances that want it;
        None, with why, when GitHub reaches none of them."""
        reasons = []
        portal = portal_url()
        if portal:
            why = github.unreachable(portal)
            if why is None:
                return portal + github.HOOK_PATH, ""
            reasons.append(f"the portal: {why}")
        for inst in sorted(wanting, key=lambda i: i.key):
            if inst.site:
                why = github.unreachable(inst.site)
                if why is None:
                    return f"{inst.site}{workspaceweb.HOOKS_PATH}github/", ""
                reasons.append(f"the name of {inst.key}: {why}")
        # the first reason only: one sentence, which the reader's language translates whole
        said = reasons[0] if reasons else "the portal has no address and the instance no name"
        return None, (f"GitHub would not reach this OmniaCLI ({said}): give the instance a name in Addresses, or "
                      "the portal an address (Options › Customers' portal)")

    def github_ours(hook: dict, rid: str | None, base: str | None) -> bool:
        """A webhook of GitHub is the one OmniaCLI made: its address is ours (the mark)."""
        url = str((hook.get("config") or {}).get("url") or "")
        return bool(rid and url.endswith(github.HOOK_PATH + rid)) or bool(base and url.startswith(base))

    def github_scopes(servers) -> list[str]:
        """The scopes of the credentials file whose GitHub tokens servers use
        (each one's own, then its workspace's), read while they are here: an
        instance deleted, its webhook is taken away with the token it was made
        with, which its server, gone, no longer names (github_token_kept)."""
        found = []
        for server in servers:
            ws = settings.workspace_of(server)
            for scope in (f"server:{server}", *((f"workspace:{ws}",) if ws else ())):
                if scope not in found:
                    found.append(scope)
        return found

    def github_token_kept(host: str, scopes) -> tuple[str, gitcredentials.Credential] | None:
        """(scope, its GitHub token for host) of the first of scopes that has one in the credentials file."""
        if settings.credentials_file is None or not scopes:
            return None
        try:
            found = gitcredentials.load(settings.credentials_file)
        except gitcredentials.CredentialError:
            return None
        for scope in scopes:
            cred = found.get(scope, {}).get(host)
            if cred is not None and cred.github:
                return scope, cred
        return None

    def github_record_url(record: dict) -> str:
        return f"https://{record.get('host')}/{record.get('repository')}.git"

    async def github_urls_of(servers, scopes=()) -> set[str]:
        """The repositories of servers whose webhook OmniaCLI made (github-hooks.json): those of their instances,
        those whose record names one of them (made for its CI, or still to take away), and those still to take
        away with the token of one of scopes (a workspace deleted)."""
        servers = set(servers)
        data = await asyncio.to_thread(deployhooks.load, github_hooks_file)
        records = {k: r for k, r in data.items() if isinstance(r, dict) and r.get("host") and r.get("repository")}
        urls = {github_record_url(r) for r in records.values()
                if r.get("server") in servers or any(str(i).split("/")[0] in servers for i in r.get("instances") or [])
                or set(r.get("scopes") or ()) & set(scopes)}
        for server in servers:
            srv = settings.servers.get(server)
            for inst in (srv.instances.values() if srv is not None else ()):
                for repo in inst.repositories:
                    url = await remote_url(repo)
                    if github_key(url) in records:
                        urls.add(url)
        return urls

    async def github_after_removal(job, gone: list[str], urls: set[str], scopes: list[str]) -> None:
        """Servers gone from this machine (an instance deleted, a server's line,
        a workspace): their CI forgotten as Forget does, then the webhooks of
        urls synced as switching the CI off does: taken away where no instance
        here with the CI on follows them any more."""
        data = await asyncio.to_thread(deployhooks.load, deploy_hooks_file)
        keys = [k for k in data if str(k).split("/")[0] in gone]
        for key in keys:
            data.pop(key, None)
            await asyncio.to_thread(deploys.set_paused, deploys_folder, key, None)
        if keys:
            await asyncio.to_thread(deployhooks.save, deploy_hooks_file, data)
        if urls:
            await github_sync(job, urls, scopes)

    async def github_retry(source: str):
        """The webhooks whose last sync GitHub refused or did not answer (made
        once: an id, with why), synced again in a job; None when there is none.
        Each night (catalog_loop): an instance deleted while GitHub did not
        answer has its webhook taken away then."""
        data = await asyncio.to_thread(deployhooks.load, github_hooks_file)
        urls = {github_record_url(r) for r in data.values()
                if isinstance(r, dict) and r.get("id") and r.get("why") and r.get("host") and r.get("repository")}
        if not urls:
            return None
        return jobs.submit("GitHub webhooks synced again", [], source, lambda job: github_sync(job, urls))
    app.state.github_retry = github_retry

    async def github_sync_one(job, key: str, host: str, full: str, record: dict | None,
                              scopes=()) -> dict | None:
        """The webhook of one repository as the CI of the instances here wants
        it: made or updated, or taken away; what github-hooks.json keeps of it.
        scopes: where the token of servers gone is kept (github_scopes)."""
        stamp = datetime.datetime.now().isoformat(timespec="seconds")
        follow = await github_followers(key)
        wanting = [i for i in follow if not manual_only(i) and ci_on(i)]
        if wanting:
            found = github_token_of(host, [i.server for i in wanting])
            if found is None:
                if host == "github.com":
                    job.log(f"{full}: no GitHub token in the git credentials of {', '.join(i.key for i in wanting)}: "
                            "its webhook is pasted by hand (Modules › Updates of the code)")
                return record
            server, cred = found
            base, why = github_hook_base(wanting)
            if base is None:
                job.warn(f"The webhook of {full} on GitHub is not made: {why}")
                return {**(record or {}), "host": host, "repository": full, "why": why, "at": stamp}
            rid = (record or {}).get("rid") or secrets.token_urlsafe(9)
            url = base + rid
            secret = (record or {}).get("secret") or deployhooks.new_secret()
            async with github.Client(host, cred.token) as gh:
                hooks = await gh.hooks(full)
                mine = (next((h for h in hooks if h.get("id") == (record or {}).get("id")), None)
                        or next((h for h in hooks if github_ours(h, rid, base)), None))
                if mine is not None:
                    await gh.change_hook(full, mine["id"], url, secret)
                    hook_id = mine["id"]
                    job.log(f"GitHub: the webhook of {full} updated: {url} (push events)")
                else:
                    hook_id = (await gh.make_hook(full, url, secret))["id"]
                    job.log(f"GitHub: the webhook of {full} made: {url} (push events, content type JSON, "
                            "signed with a secret of its own)")
            job.log(f"It deploys {', '.join(i.key for i in wanting)} at a push; a production that follows {full} "
                    "is told of the new commit and is updated by hand")
            return {"host": host, "repository": full, "id": hook_id, "url": url, "rid": rid, "secret": secret,
                    "server": server, "instances": [i.key for i in wanting], "at": stamp, "why": None}
        if not record or not record.get("id"):
            return None
        found = github_token_of(host, [record.get("server") or "", *(i.server for i in follow),
                                       *sorted(settings.servers)]) \
            or github_token_kept(host, [*(record.get("scopes") or []), *scopes])
        if found is None:
            job.warn(f"The webhook of {full} on GitHub stays: no GitHub token here reaches it any more; take it "
                     "away on GitHub (the repository's Settings › Webhooks)")
            return None
        async with github.Client(host, found[1].token) as gh:
            hook = await gh.hook(full, record["id"])
            if hook is None:
                job.log(f"GitHub: the webhook of {full} was not there any more")
            elif github_ours(hook, record.get("rid"), None):
                await gh.remove_hook(full, record["id"])
                job.log(f"GitHub: the webhook of {full} taken away: no instance here with the CI on follows it")
            else:
                job.log(f"GitHub: the webhook {record['id']} of {full} has another address now, not OmniaCLI's: "
                        "left as it is")
        return None

    async def github_sync(job, urls, scopes=()) -> None:
        """The webhooks on GitHub of the repositories at urls, each as the CI of
        the instances here wants it (github_sync_one); a refusal of GitHub is a
        warning of the job, the rest goes on, and its record stays with why
        (and scopes, the token's of servers gone) for github_retry."""
        keys = {}
        for url in urls:
            found = github.repository_of(url)
            if found:
                keys[github.key_of(*found)] = found
        if not keys:
            return
        async with github_lock:
            data = await asyncio.to_thread(deployhooks.load, github_hooks_file)
            for key, (host, full) in sorted(keys.items()):
                record = data.get(key) if isinstance(data.get(key), dict) else None
                try:
                    found = await github_sync_one(job, key, host, full, record, scopes)
                except github.GitHubError as exc:
                    job.warn(f"GitHub, the webhook of {full}: {exc}"
                             + ("; it is tried again each night" if (record or {}).get("id") else ""))
                    kept = [*((record or {}).get("scopes") or []), *(x for x in scopes
                                                                      if x not in ((record or {}).get("scopes") or []))]
                    found = {**(record or {}), "host": host, "repository": full, "why": str(exc),
                             "at": datetime.datetime.now().isoformat(timespec="seconds"), **({"scopes": kept} if kept else {})}
                if found is None:
                    data.pop(key, None)
                else:
                    data[key] = found
            await asyncio.to_thread(deployhooks.save, github_hooks_file, data)

    async def github_view(request: Request, instance: Instance) -> list[dict]:
        """The webhook on GitHub of each repository of the instance a GitHub
        token reaches: made (its address), or why not."""
        lang = request_language(request)
        data = await asyncio.to_thread(deployhooks.load, github_hooks_file)
        tokens = gitcredentials.github_tokens(settings, instance.server)
        rows = []
        for repo in instance.repositories:
            found = github.repository_of(await remote_url(repo))
            if not found:
                continue
            record = data.get(github.key_of(*found))
            record = record if isinstance(record, dict) else {}
            if found[0] not in tokens and not record:
                continue
            rows.append({"name": repo.name, "repository": found[1], "made": bool(record.get("id")),
                         "url": record.get("url") if record.get("id") else None, "at": record.get("at"),
                         "why": i18n.tr(lang, record["why"]) if record.get("why") else None,
                         "token": found[0] in tokens})
        return rows

    async def github_targets(instance: Instance, followed: list[str]) -> list[tuple]:
        """(repository, host, owner/name, token) of the repositories followed a GitHub token of the instance reaches."""
        tokens = gitcredentials.github_tokens(settings, instance.server)
        found = []
        for repo in instance.repositories:
            if repo.name not in followed:
                continue
            where = github.repository_of(await remote_url(repo))
            if where and where[0] in tokens:
                found.append((repo, where[0], where[1], tokens[where[0]]))
        return found

    GITHUB_STATES = {"pending": "Deploying on {key}", "success": "Deployed on {key}",
                     "failure": "The deploy on {key} failed", "error": "The deploy on {key} was stopped"}

    async def github_status(job, instance: Instance, targets: list[tuple], state: str, sha: str) -> None:
        """The state of a deploy of a test or a staging written on the commit
        (context omniacli/<instance>, a link to its job when the portal has a
        public address): the commit pushed while it runs or fails, the one
        checked out when it succeeds. A token that may not write it: said in a
        line, the deploy goes on."""
        if not targets or manual_only(instance):
            return
        portal = portal_url()
        link = f"{portal}/jobs/{job.id}" if portal and github.unreachable(portal) is None else None
        context = f"{github.CONTEXT}/{instance.server}" + ("" if instance.role == "production" else f"/{instance.role}")
        for repo, host, full, cred in targets:
            commit = sha if state != "success" and sha else await deploys.head(repo)
            if not commit or not github.SHA.fullmatch(commit):
                continue
            try:
                async with github.Client(host, cred.token) as gh:
                    await gh.set_status(full, commit, state, context, GITHUB_STATES[state].format(key=instance.key),
                                        link)
                job.log(f"GitHub: {context} {state} on {full}@{commit[:10]}")
            except github.GitHubError as exc:
                job.log(f"GitHub: the state of the deploy is not written on {full}: {exc}")

    async def github_hook_call(request: Request):
        """A push told by a webhook OmniaCLI made on GitHub (its secret signs the
        body): every instance here that follows that repository and branch, as
        the per-instance webhook does it: a test or a staging with the CI on
        deploys, one with the CI off notes it, a production lists the new
        commit and is not touched (updated by hand only). A Starlette route: no
        login, the signature is its check."""
        rid = request.path_params["rid"]
        data = await asyncio.to_thread(deployhooks.load, github_hooks_file)
        key, record = next(((k, r) for k, r in data.items() if isinstance(r, dict) and r.get("rid") == rid
                            and r.get("secret")), (None, None))
        body = await request.body()
        headers = {k.lower(): v for k, v in request.headers.items()}
        ip = request.client.host if request.client else ""
        if record is None or not headers.get("x-hub-signature-256") \
                or not deployhooks.verified(headers, body[:deployhooks.MAX_BODY], record["secret"]):
            access_log.record("failed", "hook", "", ip, f"GitHub webhook {rid[:6]}…")
            return JSONResponse({"error": "Unknown webhook or wrong signature"}, status_code=403)
        event = headers.get("x-github-event", "push")
        if event == "ping":
            return JSONResponse({"ok": True, "pong": True})
        if event != "push":
            return JSONResponse({"ok": True, "note": f"not a push: {event}"})
        branch, urls = deployhooks.pushed(body)
        sha, message = deployhooks.head_commit(body)
        # only the repository this webhook is of
        urls &= {deployhooks.host_path(f"https://{record['host']}/{record['repository']}")}
        stamp = datetime.datetime.now().isoformat(timespec="seconds")
        notes, started = [], []
        hooks = deployhooks.load(deploy_hooks_file)
        for inst in (settings.all_instances() if branch and urls else []):
            followed = await followed_by(inst, urls, branch)
            if not followed:
                continue
            if manual_only(inst):
                await note_available(inst, followed, branch, sha, message, deployhooks.head_author(body))
                result = (f"not deployed: {inst.key} is a production, updated by hand only; the new commit of "
                          f"{', '.join(followed)} is listed on its page")
            elif not ci_on(inst):
                result = f"not deployed: the CI of {inst.key} is off"
            else:
                job = push_deploy(inst, followed, branch, sha)
                started.append(job.id)
                result = "deploy"
            notes.append(result if result != "deploy" else f"{inst.key}: deploy")
            if inst.key in hooks:
                hooks[inst.key]["last"] = {"time": stamp, "branch": branch, "result": result, "by": "github",
                                           **({"job": started[-1]} if result == "deploy" else {})}
        if notes:
            await asyncio.to_thread(deployhooks.save, deploy_hooks_file, hooks)
        note = "; ".join(notes) or f"nothing to do: no instance here follows branch {branch or '?'} of {record['repository']}"
        access_log.record("action", "hook", "push", ip, f"GitHub webhook of {record['repository']}: {note}"[:300])
        answer = {"ok": True, "note": note}
        if started:
            answer.update(job=started[0], jobs=started)
        return JSONResponse(answer, status_code=202 if started else 200)

    app.add_route(github.HOOK_PATH + "{rid}", github_hook_call, methods=["POST"])
    app.add_route(workspaceweb.HOOKS_PATH + "github/{rid}", github_hook_call, methods=["POST"])

    async def productions_by_hand() -> None:
        """Once, after the upgrade that made a production updated by hand only: a
        job of the system names each production whose deploy on push or auto
        update was on, and what it does from now (deploys/by-hand.json: told)."""
        told_file = deploys_folder / "by-hand.json"
        try:
            told = set(json.loads(told_file.read_text(encoding="utf-8")).get("told") or [])
        except (OSError, ValueError, AttributeError):
            told = set()
        hooks = deployhooks.load(deploy_hooks_file)
        lines = []
        for inst in settings.all_instances():
            if inst.key in told or not manual_only(inst):
                continue
            if inst.key in hooks:
                lines.append((inst.key, f"{inst.key}: a push of its branch is no longer deployed on it: it is "
                                        "listed on its page as a new commit available, and deploys its stagings "
                                        "on that branch"))
            if inst.auto_update.enabled:
                lines.append((inst.key, f"{inst.key}: its auto update (every {inst.auto_update.interval_minutes} "
                                        "min) does not run any more: Git pull and restart by hand"))
        if not lines:
            return
        keys = sorted({key for key, _ in lines})

        async def action(job):
            job.log(BY_HAND)
            for _, line in lines:
                job.log(line)

        jobs.submit("Productions updated by hand only", keys, "system: an upgrade of OmniaCLI", action)
        deploys_folder.mkdir(parents=True, mode=0o700, exist_ok=True)
        told_file.write_text(json.dumps({"told": sorted(told | set(keys))}), encoding="utf-8")

    updater.manual_only = manual_only
    scheduler.manual_only = manual_only


    # --- the deploys of an instance and going back to one (deploys.py) ---------

    def deploy_when(entry: dict) -> str:
        return str(entry.get("finished") or entry.get("started") or "")[:16].replace("T", " ")

    def deploy_rows(request: Request, instance: Instance, entries: list, now: dict) -> list:
        """The deploys newest first as the page shows them: for a user of
        workspaces without the integrator's names (customerview.py)."""
        return deploy_rows_for(customer_view(request), request_language(request), instance, entries, now)

    async def mcp_deploys(instance: Instance, workspace: str) -> dict:
        """MCP's list_deploys: the rows of the page, in English, a workspace's token's without the
        integrator's names."""
        data = await asyncio.to_thread(deploys.load, deploys_folder, instance.key)
        view = customer_view_of({workspace}, "en") if workspace else None
        return {"ci": ci_on(instance),
                "deploys": deploy_rows_for(view, "en", instance, data["deploys"], await deploys.snapshot(instance))}

    def deploy_seconds(entry: dict) -> int | None:
        try:
            began = datetime.datetime.fromisoformat(str(entry.get("started")))
            ended = datetime.datetime.fromisoformat(str(entry.get("finished")))
        except (TypeError, ValueError):
            return None
        return max(0, int((ended - began).total_seconds()))

    def deploy_rows_for(view, lang: str, instance: Instance, entries: list, now: dict) -> list:
        folder = backup_folder(instance)
        kept = {p.name for p in folder.glob("*.zip")} if folder.is_dir() else set()
        current_sha = {name: row.get("sha") for name, row in now.items()}
        rows, current_found = [], False
        for entry in reversed(entries):
            state = {name: (row or {}).get("sha") for name, row in (entry.get("state") or {}).items()}
            current = not current_found and bool(state) and all(current_sha.get(n) == sha for n, sha in state.items())
            current_found = current_found or current
            by = str(entry.get("by") or "")
            title, error = str(entry.get("title") or ""), entry.get("error")
            if view is not None:
                by, title = view.source(by), view.text(title)
                error = view.text(error) if error else error
            backup = entry.get("backup")
            rows.append({
                "id": entry.get("id"), "finished": entry.get("finished"), "started": entry.get("started"),
                "title": i18n.tr(lang, title), "by": i18n.tr(lang, by), "outcome": entry.get("outcome"),
                "error": i18n.tr(lang, error) if error else None,
                "job": f"/jobs/{entry['job']}" if entry.get("job") and jobs.get(entry["job"]) else None,
                "repositories": [{k: r.get(k) for k in ("name", "branch", "before", "after", "subject", "author",
                                                        "before_subject", "brought", "taken", "commits")}
                                 for r in entry.get("repositories") or [] if isinstance(r, dict)],
                # how long its job took, in seconds (UX-015: the card's 0:33)
                "seconds": deploy_seconds(entry),
                # a deploy whose commits are known: one it may go back to (not a commit available, not a job of the
                # code that failed before moving one)
                "has_state": bool(state) and (entry.get("kind") or "deploy") == "deploy",
                "backup": {"name": backup, "kept": backup in kept} if backup else None,
                "back_to": entry.get("back_to"), "current": current, "kind": entry.get("kind") or "deploy",
                # the time its users were not served, measured by an update of an instance switched to the update
                # without stopping (zerodowntime.py)
                "unserved": ({k: entry["unserved"].get(k) for k in ("seconds", "failed", "asked", "how")}
                             if isinstance(entry.get("unserved"), dict) else None)})
        return rows

    async def available_now(instance: Instance, entries: list) -> list[dict]:
        """The new commits a push listed on a production and not pulled yet:
        the newest of each repository whose commit is not checked out (nor
        an ancestor of what is) and that no deploy after it changed."""
        found, seen = [], set()
        repos = {r.name: r for r in instance.repositories}
        for entry in reversed(entries):
            for row in entry.get("repositories") or []:
                name = row.get("name")
                if name in seen or name not in repos:
                    continue
                seen.add(name)
                if entry.get("kind") != "available":
                    continue
                sha, head = row.get("after") or "", await deploys.head(repos[name])
                if sha and head and (head.startswith(sha) or (await ops.capture(
                        ["git", "merge-base", "--is-ancestor", sha, head], cwd=repos[name].path, timeout=20))[0] == 0):
                    continue
                found.append({"name": name, "branch": row.get("branch") or repos[name].branch, "sha": sha[:10],
                              "subject": row.get("subject") or "", "time": entry.get("finished"),
                              "author": row.get("author") or "", "by": str(entry.get("by") or ""),
                              "id": entry.get("id"), "after": sha})
        return found

    def deploys_pause_view(request: Request, instance: Instance, me: Principal) -> dict:
        stopped = deploys.paused(deploys_folder, instance.key)
        view = customer_view(request)
        if stopped and view is not None:
            stopped = {**stopped, "by": view.who(str(stopped.get("by") or ""))}
        return {"paused": stopped, "ci": ci_on(instance),
                "auto_update": instance.auto_update.enabled and not manual_only(instance),
                "automatic": not manual_only(instance),
                "can_pause": me.can(backup_role(instance)), "pause_role": backup_role(instance)}

    @app.get("/api/servers/{server}/{role}/deploys", dependencies=[Depends(developer)])
    async def deploys_list(request: Request, server: str, role: str, me: Principal = Depends(current_user)):
        """The deploys of the instance, newest first (the last deploys.KEEP),
        which one its code is at now, and whether its automatic deploys are
        paused."""
        instance = get_instance(server, role)
        data = await asyncio.to_thread(deploys.load, deploys_folder, instance.key)
        now = await deploys.snapshot(instance)
        return {"deploys": deploy_rows(request, instance, data["deploys"], now), "keep": deploys.KEEP,
                "available": await available_now(instance, data["deploys"]) if manual_only(instance) else [],
                "can_back": me.can("developer") and bool(instance.repositories),
                **deploys_pause_view(request, instance, me)}

    @app.get("/api/servers/{server}/{role}/deploys/{deploy_id}/back", dependencies=[Depends(developer)])
    async def deploy_back_plan(request: Request, server: str, role: str, deploy_id: str,
                               me: Principal = Depends(current_user)):
        """What «Back to this deploy» would do now: the commits each
        repository moves to, those taken away, the backup made before that
        deploy and whether it is still there, what the next push does."""
        instance = get_instance(server, role)
        entry = deploys.find(deploys_folder, instance.key, deploy_id)
        if entry is None:
            return refuse(f"No deploy {deploy_id} of {instance.key}", status.HTTP_404_NOT_FOUND)
        plan = await deploys.back_plan(instance, entry)
        lang = request_language(request)
        # the second way: the database as it was with this deploy's code is the backup made before the
        # first deploy that came after it (the oldest of those going back takes away)
        entries = [d for d in deploys.load(deploys_folder, instance.key)["deploys"]
                   if (d.get("kind") or "deploy") == "deploy"]
        at = next((i for i, d in enumerate(entries) if d.get("id") == deploy_id), len(entries))
        after = entries[at + 1] if at + 1 < len(entries) else None
        second = None
        if after is not None:
            name = after.get("backup")
            second = {"name": name, "before": after.get("started") or after.get("finished"),
                      "kept": bool(name) and (backup_folder(instance) / name).is_file()}
        return {**plan, "refused": [i18n.tr(lang, r) for r in plan["refused"]], "when": entry.get("finished"),
                "restore_backup": second, **deploys_pause_view(request, instance, me)}

    @app.post("/api/servers/{server}/{role}/deploys/{deploy_id}/back", dependencies=[Depends(developer)])
    async def deploy_back(server: str, role: str, deploy_id: str, payload: dict = Body(default={}),
                          me: Principal = Depends(current_user)):
        """«Back to this deploy»: a job that backs the instance up, checks
        out in each repository the commit of that deploy, updates the
        changed modules and restarts; with pause, the automatic deploys
        paused first (a push would deploy the branch head again). On a
        production, the name of its server written to confirm (UX-015 D2), as
        the REST API asks it."""
        instance = get_instance(server, role)
        if manual_only(instance) and str(payload.get("confirm") or "") != instance.server:
            return refuse(f"Write the name of the instance, {instance.server}, to go back on a production")
        found = await start_deploy_back(instance, deploy_id, me, bool(payload.get("pause")), f"manual: {me}")
        return found if isinstance(found, JSONResponse) else {"job": found.id}

    async def start_deploy_back(instance: Instance, deploy_id: str, me: Principal, pause: bool, source: str):
        """The job of «Back to this deploy» (the page, the REST API, MCP), or the refusal (a JSONResponse)."""
        entry = deploys.find(deploys_folder, instance.key, deploy_id)
        if entry is None:
            return refuse(f"No deploy {deploy_id} of {instance.key}", status.HTTP_404_NOT_FOUND)
        if (entry.get("kind") or "deploy") != "deploy" or not entry.get("state"):
            return refuse(f"{deploy_id} moved no commit of {instance.key}: there is nothing to go back to")
        pause = pause and ci_on(instance)
        if pause and not me.can(backup_role(instance)):
            return refuse(f"The {backup_role(instance)} role switches the CI of {instance.key} off",
                          status.HTTP_403_FORBIDDEN)
        plan = await deploys.back_plan(instance, entry)
        if plan["refused"]:
            return refuse("; ".join(plan["refused"]))
        if not plan["changes"]:
            return refuse(f"The code of {instance.key} is at that deploy already")
        who = str(me)

        async def action(job):
            if pause:
                await asyncio.to_thread(deploys.set_paused, deploys_folder, instance.key, who)
                job.log(f"--- the CI of {instance.key} switched off: a push, the auto update and a scheduled pull "
                        "do not move its code until it is switched on again")
            await deploys.go_back(job, instance, entry, backup_folder(instance))

        ws = workspace_of(instance.server)
        return jobs.submit(f"Back to the deploy of {deploy_when(entry)} on {instance.key}", [instance.key],
                           source, action, workspace=ws[0].name if ws else "")


    # --- the environments and their deploys (UX-015), the Overview's «Environments and deploys» -------------------
    # A row per environment of a production (it, its test, its stagings here, those on the linked machines): its
    # state, its branch, its CI, and its last deploys as cards, as the builds of Odoo.sh. The rows come with the
    # page (environment_rows); the cards after it, in one request for the section (GET …/environments), for who
    # may update the code: the strip of each environment, its newest deploys, which one its code is at now, the
    # job working on it, the commit a push brought to a production and not deployed.

    # the cards of deploys a strip shows at most (1280 px and over); the page shows fewer on a narrower screen
    STRIP_DEPLOYS = 3

    async def repository_webs(instance: Instance) -> dict:
        """{repository: its page on GitHub or GitLab, or None}, from its remote's address."""
        async def one(repo):
            if not repo.path.is_dir():
                return repo.name, None
            code, out = await ops.capture(repo.git("remote", "get-url", repo.remote), cwd=repo.path, timeout=10)
            url = out.strip() if code == 0 else ""
            return repo.name, workspaceops.web_url(url) if url else None
        return dict(await asyncio.gather(*(one(r) for r in instance.repositories)))

    def strip_message(repos: list, order: list, deploy: bool = True) -> dict:
        """What a card says of its commits: the message of the repository that brought the most of them (a tie:
        the first in the instance's order), its author, and the others with how many each brought."""
        if not repos:
            return {"repo": "", "message": "", "sha": "", "author": "", "change": None, "others": []}
        rank = {name: i for i, name in enumerate(order)}
        main = min(repos, key=lambda r: (-(r.get("brought") or (1 if r.get("after") else 0)),
                                         rank.get(r.get("name"), len(rank))))
        change = None
        if deploy and not main.get("before"):
            change = "added"
        elif deploy and not main.get("after"):
            change = "removed"
        return {"repo": main.get("name") or "", "message": main.get("subject") or "", "sha": main.get("after") or "",
                "author": main.get("author") or "", "change": change,
                "others": [{"name": r.get("name") or "", "brought": r.get("brought")} for r in repos if r is not main]}

    def strip_link(found: dict, webs: dict) -> str | None:
        web = webs.get(found.get("repo"))
        return workspaceops.commit_url(web, found["sha"]) if web and found.get("sha") else None

    async def environment_strip(request: Request, me: Principal, instance: Instance) -> dict:
        """The strip of one environment: its cards, the special ones first (a job working on it, the commit a
        push brought to a production, the code of now when no deploy recorded is it), then its newest deploys
        and the one its code is at; how many deploys it has in all (Modules › Deploys lists them)."""
        view, lang, prefix = customer_view(request), request_language(request), prefix_of(request)
        data = await asyncio.to_thread(deploys.load, deploys_folder, instance.key)
        entries = data["deploys"]
        rows = deploy_rows_for(view, lang, instance, entries, await deploys.snapshot(instance))
        webs = await repository_webs(instance)
        order = [r.name for r in instance.repositories]
        can_back = me.can("developer") and bool(instance.repositories)
        cards = []
        busy = jobs.running_on(instance.key)
        if busy is not None:
            cards.append({"kind": "busy", "job": f"/jobs/{busy.id}",
                          "title": i18n.tr(lang, view.text(busy.title) if view else busy.title)})
        if manual_only(instance):
            found = await available_now(instance, entries)
            if found:
                said = strip_message([{"name": a["name"], "subject": a["subject"], "after": a["after"],
                                       "author": a["author"], "brought": 1} for a in found], order, deploy=False)
                cards.append({"kind": "available", "ids": [a["id"] for a in found if a.get("id")], **said,
                              "url": strip_link(said, webs), "finished": max(str(a.get("time") or "") for a in found),
                              "by": i18n.tr(lang, view.source(found[0]["by"]) if view else found[0]["by"]),
                              "outcome": "available"})
        listed = [r for r in rows if r["kind"] != "available"]
        current = next((r for r in listed if r["current"]), None)
        if current is None and instance.repositories:
            code = await deploys.code_now(instance)
            if code:
                said = strip_message(code, order, deploy=False)
                cards.append({"kind": "now", "ids": [], **said, "url": strip_link(said, webs), "current": True})
        shown = listed[:STRIP_DEPLOYS]
        if current is not None and current not in shown:
            shown.append(current)
        by_id = {r["id"]: r for r in listed}
        for row in shown:
            # a deploy gone back to another: it says that one's commits (the code it brought back)
            target = by_id.get(row.get("back_to")) if row.get("back_to") else None
            said = strip_message((target or row)["repositories"], order)
            if not row["repositories"]:
                # a job of the code that failed before moving a commit (UX-015 D4): its title says what it was
                said["message"] = row["title"]
            cards.append({"kind": row["kind"], "id": row["id"], "ids": [row["id"]], **said, "url": strip_link(said, webs),
                          "outcome": row["outcome"], "current": row["current"], "by": row["by"],
                          "started": row["started"], "finished": row["finished"], "seconds": row["seconds"],
                          "unserved": (row["unserved"] or {}).get("seconds"), "error": row["error"], "job": row["job"],
                          "back": can_back and row["has_state"] and not row["current"]
                          and row["outcome"] in ("success", "warned")})
        page = environment_page(prefix, instance)
        return {"key": instance.key, "server": instance.server, "role": instance.role, "total": len(entries),
                "cards": cards, "repositories": len(instance.repositories),
                "ci": "manual" if manual_only(instance) else ("on" if ci_on(instance) else "off"),
                "api": f"{prefix}/api/servers/{instance.server}/{instance.role}/deploys",
                # going back on a production: its server's name written first (D2)
                "confirm": instance.server if manual_only(instance) else "",
                "more": page + "#deploys", "open": instance.web_url or None}

    async def environment_rows(request: Request, me: Principal, srv, view: str, staging_of: dict | None,
                               state: str, staging_now: list, login_offers: dict, addresses: dict) -> list:
        """The rows of «Environments and deploys» (UX-015 §5, §7), as the page draws them before the cards: on a
        production's page, it, its test and its stagings here (those of the linked machines come from the
        browser); on a test's or a staging's page, itself. Each with its state, its branch, its CI, its
        Repository ↗, its copy's date (a staging), its Rebuild… and the menu of its card of now (Log in as…,
        Log, Back up now…, Shell, Addresses…), decided here for me: absent, off with why, or there."""
        prefix, lang = prefix_of(request), request_language(request)
        if staging_of or view == "test":
            envs = [(srv.instances[view], "staging" if staging_of else "test", None, state)]
        else:
            envs = [(srv.production, "production", None, state)]
            if srv.test is not None:
                envs.append((srv.test, "test", None, await run_state(srv.test)))
            envs += [(settings.servers[r["server"]].production, "staging", r, r["state"]) for r in staging_now]
        rows = []
        for inst, kind, staging, st in envs:
            role = role_on(me, inst.server)
            code = reaches(role, "developer") and not refusal(me, "code", None, [inst.server])
            page = environment_page(prefix, inst)
            label = host_label(inst) if kind != "test" else (host_label(inst, "") or "Test")
            branches = list(dict.fromkeys(r.branch for r in inst.repositories))
            repo = None
            if code and inst.repositories:
                first = inst.repositories[0]
                web = (await repository_webs(inst)).get(first.name)
                url = workspaceops.branch_url(web, first.branch)
                if url:
                    repo = {"url": url, "name": first.name, "branch": first.branch,
                            "others": len(inst.repositories) - 1}
            menu = []
            offer = login_offers.get(inst.key)
            if offer:
                menu.append({"kind": "login_as", "offer": offer})
            why = refusal(me, "logs", None, [inst.server])
            menu.append({"kind": "logs", "url": page + "#log", "disabled": i18n.tr(lang, why) if why else ""})
            if reaches(role, "developer") and inst.plugin.has_backup:
                why = refusal(me, "backup", None, [inst.server])
                menu.append({"kind": "backup", "url": f"{prefix}/servers/{inst.server}/{inst.role}/backup",
                             "key": inst.key, "disabled": i18n.tr(lang, why) if why else ""})
            if reaches(role, "developer") and not me.scoped:
                if getattr(inst.plugin, "container_shell", None) is not None:
                    menu.append({"kind": "shell", "url": f"{prefix}/servers/{inst.server}/{inst.role}/terminal",
                                 "container": True})
                elif settings.machine == MACHINE_DEVELOPMENT:
                    menu.append({"kind": "shell", "url": f"{prefix}/servers/{inst.server}/{inst.role}/shell",
                                 "container": False})
            address = addresses.get(f"{inst.server}/{inst.role}")
            if address and address.get("can"):
                menu.append({"kind": "addresses", "env": f"{inst.server}/{inst.role}"})
            elif address and address.get("reason") and me.can("admin"):
                menu.append({"kind": "addresses", "env": f"{inst.server}/{inst.role}",
                             "disabled": i18n.tr(lang, address["reason"])})
            rebuild = None
            if kind == "staging" and staging is not None and me.can("admin"):
                why = refusal(me, "stagings", None, [inst.server]) or (
                    REBUILD_NOT_YOURS if refusal(me, None, None, [srv.name]) else None)
                rebuild = {"server": inst.server, "disabled": i18n.tr(lang, why) if why else ""}
            parts = urlsplit(inst.web_url or "")
            rows.append({
                "key": inst.key, "server": inst.server, "role": inst.role, "kind": kind, "label": label,
                # its page, a link (none for the page in view)
                "page": None if inst.key == srv.instances[view].key else page,
                "state": "busy" if jobs.is_busy(inst.key) else st, "stopped": st == "stopped",
                # Open ↗: an address the browser opens (its name, or localhost when the browser is on this machine)
                "open": inst.web_url if inst.web_url and (parts.scheme == "https" or (
                    parts.hostname in ("localhost", "127.0.0.1") and not prefix_of(request))) else None,
                "code": code, "repositories": len(inst.repositories),
                "branch": branches[0] if len(branches) == 1 else "",
                "branches": " · ".join(f"{r.name}: {r.branch}" for r in inst.repositories),
                "repo": repo,
                "ci": None if not inst.repositories else (
                    "manual" if manual_only(inst) else ("on" if ci_on(inst) else "off")),
                "ci_url": page + "#updates", "deploys_url": page + "#deploys",
                "copied": (staging or {}).get("created") or "",
                "rebuild": rebuild, "menu": menu})
        return rows

    def host_label(inst: Instance, fallback: str | None = None) -> str:
        """An environment's name as the rows say it: its address without the scheme, or its server's name."""
        url = inst.web_url or ""
        if url and "://localhost" not in url and "://127.0.0.1" not in url:
            return url.split("://", 1)[-1]
        return inst.server if fallback is None else fallback

    def environment_page(prefix: str, instance: Instance) -> str:
        """The page of an environment: a test is its production's page at ?view=test."""
        return f"{prefix}/servers/{instance.server}" + ("?view=test" if instance.role == "test" else "")

    def strip_environments(me: Principal, instance: Instance) -> list[Instance]:
        """The environments of the section on the page of instance: a production's page lists it, its test and
        its stagings of this machine (those me sees, with the capability to update the code); a test's or a
        staging's page itself only."""
        found = [instance]
        if instance.role == "production" and manual_only(instance):
            srv = settings.servers[instance.server]
            if srv.test is not None:
                found.append(srv.test)
            shown = visible_servers(me)
            for row in staging_rows(instance.server):
                if (shown is None or row["server"] in shown) and reaches(role_on(me, row["server"]), "developer") \
                        and not refusal(me, "code", None, [row["server"]]):
                    found.append(settings.servers[row["server"]].production)
        return found

    @app.get("/api/servers/{server}/{role}/environments", dependencies=[Depends(developer)])
    async def environments_strips(request: Request, server: str, role: str, me: Principal = Depends(current_user)):
        """The cards of the section «Environments and deploys» (UX-015): on a production's page, of it, its test
        and its stagings here; on a test's or a staging's page, of itself. One request for the section."""
        instance = get_instance(server, role)
        found = await asyncio.gather(*(environment_strip(request, me, i) for i in strip_environments(me, instance)))
        return {"environments": list(found), "shown": STRIP_DEPLOYS}

    @app.get("/api/servers/{server}/stagings/elsewhere/environments", dependencies=[Depends(admin)])
    async def stagings_elsewhere_strips(request: Request, server: str, link: str = "", staging: list[str] = Query([]),
                                        me: Principal = Depends(current_user)):
        """The cards of the stagings of server on the linked machine link (UX-015 §11): each one's
        environments there (GET /api/servers/<staging>/production/environments, through the link, LIST_TIMEOUT),
        its moments moved onto this machine's clock, its addresses under the link's prefix; a machine that does
        not answer, or an older OmniaCLI, says why for each of its rows."""
        target = settings.link_targets.get(link)
        if not chooses_machine(me) or target is None or server not in settings.servers:
            return refuse("No such link", status.HTTP_404_NOT_FOUND)
        names = [n for n in dict.fromkeys(staging) if _STAGING_PARENT.fullmatch(n)][:20]
        headers = {**link_headers(target, me.name, me.role), "Accept": "application/json",
                   "Accept-Language": request_language(request)}
        under = f"{prefix_of(request)}/links/{link}"

        async def ask(name: str) -> dict:
            try:
                resp = await asyncio.wait_for(link_clients.client(target).get(
                    f"/api/servers/{name}/production/environments", headers=headers, timeout=LIST_TIMEOUT), LIST_TIMEOUT)
            except (httpx.HTTPError, asyncio.TimeoutError) as exc:
                return {"server": name, "unread": describe_error(exc)}
            if resp.status_code == 404:
                return {"server": name, "older": True}
            try:
                data = clock.answered_here(resp, resp.json()) if resp.status_code == 200 else None
            except ValueError:
                data = None
            if not isinstance(data, dict) or not isinstance(data.get("environments"), list):
                return {"server": name, "unread": f"answered HTTP {resp.status_code}"}
            env = next((e for e in data["environments"] if isinstance(e, dict)), None)
            if env is None:
                return {"server": name, "unread": "no environment in the answer"}
            # its addresses are of the machine there: through this machine's link
            for field in ("api", "more"):
                if isinstance(env.get(field), str) and env[field].startswith("/"):
                    env[field] = under + env[field]
            for card in env.get("cards") or []:
                if isinstance(card, dict) and isinstance(card.get("job"), str) and card["job"].startswith("/"):
                    card["job"] = f"/links/{link}" + card["job"]
            env["link"] = link
            return {"server": name, "environment": env}
        found = await asyncio.gather(*(ask(n) for n in names))
        lang = request_language(request)
        for row in found:
            if row.get("unread"):
                row["unread"] = i18n.tr(lang, row["unread"])
        return {"link": link, "stagings": list(found)}


    app.add_route("/hooks/deploy/{server}/{role}", deploy_hook_call, methods=["POST"])
    # the same on an instance's own name, which its nginx passes here
    app.add_route(workspaceweb.HOOKS_PATH + "deploy/{server}/{role}", deploy_hook_call, methods=["POST"])

    @app.post("/api/servers/{server}/{role}/backups/delete")
    async def backup_delete(request: Request, server: str, role: str, payload: dict = Body(...),
                            me: Principal = Depends(current_user)):
        """A backup of the instance deleted (an admin's for a production)."""
        instance = get_instance(server, role)
        if not me.can(backup_role(instance)):
            raise HTTPException(status.HTTP_403_FORBIDDEN, f"The {backup_role(instance)} role is required")
        name = str(payload.get("file") or "")
        folder = backup_folder(instance).resolve()
        path = (folder / name).resolve()
        if not _BACKUP_NAME.fullmatch(name) or path.parent != folder or not path.is_file():
            return refuse("No such backup", status.HTTP_404_NOT_FOUND)
        if jobs.is_busy(instance.key):
            return refuse(f"A job is running on {instance.key}: try again when it ends")
        path.unlink()
        access_log.record("delete backup", me.kind, me.name, request.client.host if request.client else "",
                          f"{instance.key}/{name}")
        return {"ok": True}

    async def remote_of(instance: Instance) -> "destinations.Destination | None":
        sch = scheduler.schedules.get(backup_schedule_name(instance))
        name = sch.backup.destination if sch is not None and sch.backup else ""
        return load_destinations().get(name) if name else None

    @app.get("/api/servers/{server}/{role}/remote-backups", dependencies=[Depends(developer)])
    async def remote_backups(server: str, role: str, me: Principal = Depends(current_user)):
        """The copies of the instance's backups in the destination of its
        automatic backups, newest first."""
        instance = get_instance(server, role)
        dest = await remote_of(instance)
        if dest is None:
            return {"destination": None, "files": []}
        try:
            files = await destinations.listing(dest, destinations.instance_folder(instance))
        except JobFailed as exc:
            return JSONResponse({"error": str(exc), "destination": dest.name}, status_code=502)
        local = backup_folder(instance)
        return {"destination": {"name": dest.name, "label": dest.label, "path": dest.path},
                "files": [{**f, "here": (local / f["file"]).exists()} for f in files],
                "can_fetch": me.can(backup_role(instance))}

    @app.post("/api/servers/{server}/{role}/remote-backups/fetch")
    async def remote_backup_fetch(request: Request, server: str, role: str, payload: dict = Body(...),
                                  me: Principal = Depends(current_user)):
        """A copy brought back into the instance's backups, decrypted: a job.
        Restoring it is then the Backups tab's Restore."""
        instance = get_instance(server, role)
        if not me.can(backup_role(instance)):
            raise HTTPException(status.HTTP_403_FORBIDDEN, f"The {backup_role(instance)} role is required")
        dest = await remote_of(instance)
        name = str(payload.get("file") or "")
        if dest is None:
            return refuse("The automatic backups of this instance have no destination")
        if not name.endswith(destinations.SUFFIX) or not _BACKUP_NAME.fullmatch(name[:-len(destinations.SUFFIX)]):
            return refuse("No such copy", status.HTTP_404_NOT_FOUND)
        folder = backup_folder(instance)
        job = jobs.submit(f"Bring back {name[:-len(destinations.SUFFIX)]} from {dest.name}", [instance.key],
                          f"manual: {me}", lambda job: destinations.fetch(
                              job, dest, destinations.instance_folder(instance), name, folder))
        return {"job": job.id}

    # --- remote destinations of the backups -----------------------------

    destinations_lock = asyncio.Lock()

    def destination_rows(workspace: str | None) -> list:
        """The destinations of a workspace ("" the machine's, None all of them),
        as the page shows them, and which schedules use each."""
        used = {}
        for sch in scheduler.schedules.values():
            if sch.backup and sch.backup.destination:
                used.setdefault(sch.backup.destination, []).append(sch.instance)
        return [{**d.public(), "used_by": sorted(used.get(d.name, []))}
                for d in sorted(load_destinations().values(), key=lambda d: (d.workspace, d.name))
                if workspace is None or d.workspace == workspace]

    def destination_kinds(request: Request) -> dict:
        """The kinds and their settings, in the page's language."""
        lang = request_language(request)
        return {k: {"label": i18n.tr(lang, label),
                    "settings": [{**s.to_dict(), "label": i18n.tr(lang, s.label), "help": i18n.tr(lang, s.help)}
                                 for s in found]}
                for k, (label, _, found) in destinations.KINDS.items()}

    async def destination_save(workspace: str, payload: dict):
        """A destination of workspace ("": the machine's) made or changed:
        a secret left empty keeps the saved one; a new one gets a key (or the
        one given: copies made before, elsewhere, can be read again)."""
        name = str(payload.get("name") or "").strip()
        async with destinations_lock:
            found = await asyncio.to_thread(load_destinations)
            current = found.get(name)
            if payload.get("new") and current is not None:
                return refuse(f"A destination {name} exists already")
            if current is not None and current.workspace != workspace:
                return refuse(f"No destination {name} here", status.HTTP_404_NOT_FOUND)
            kind = str(payload.get("kind") or "")
            try:
                checked = destinations.check_settings(
                    kind, payload.get("settings") or {}, current.settings if current and current.kind == kind else {})
            except ConfigError as exc:
                return refuse(str(exc))
            key = current.key if current is not None else (str(payload.get("key") or "").strip()
                                                           or new_key())
            data = {"kind": kind, "path": str(payload.get("path") or ""), "workspace": workspace,
                    "settings": checked, "key": key}
            try:
                dest = destinations.parse_destination(name, data)
            except ConfigError as exc:
                return refuse(str(exc).removeprefix(f"destinations.{name}: ").removeprefix(f"destinations.{name}."))
            try:
                await asyncio.to_thread(destinations.save_destinations, settings.destinations_file,
                                        {**found, name: dest})
            except OSError as exc:
                return refuse(f"Cannot write {settings.destinations_file}: {exc}", 500)
        return {"ok": True, "destination": dest.public(), "new_key": current is None}

    async def destination_delete(workspace: str, payload: dict):
        name = str(payload.get("name") or "")
        async with destinations_lock:
            found = await asyncio.to_thread(load_destinations)
            if name not in found or found[name].workspace != workspace:
                return refuse(f"No destination {name} here", status.HTTP_404_NOT_FOUND)
            users = [s.instance for s in scheduler.schedules.values() if s.backup and s.backup.destination == name]
            if users:
                return refuse(f"The automatic backups of {', '.join(sorted(users))} go to {name}: choose another first")
            found.pop(name)
            await asyncio.to_thread(destinations.save_destinations, settings.destinations_file, found)
        return {"ok": True}

    def destination_of(workspace: str, payload: dict):
        found = load_destinations().get(str(payload.get("name") or ""))
        if found is None or found.workspace != workspace:
            raise HTTPException(status.HTTP_404_NOT_FOUND, "No such destination here")
        return found

    async def destination_check(workspace: str, payload: dict):
        """The destination reached and written now (a file put and removed)."""
        dest = destination_of(workspace, payload)
        try:
            return {"ok": True, "message": await destinations.check(dest)}
        except JobFailed as exc:
            return refuse(str(exc), status.HTTP_502_BAD_GATEWAY)

    def destination_key(request: Request, me: Principal, workspace: str, payload: dict):
        """The destination's key, to keep elsewhere: without it, its copies
        cannot be read back on another machine."""
        dest = destination_of(workspace, payload)
        access_log.record("show destination key", me.kind, me.name, request.client.host if request.client else "",
                          dest.name)
        return {"key": dest.key}

